package com.eneik.production.services.design.sovereign.domain;

import java.util.List;
import java.util.Objects;

/**
 * Audit result generated by VisionAuditLoop.
 */
public record VisionAuditReport(
        double overallScore,
        DeonticGateResult deonticGateResult,
        List<CorrectionDirective> correctionDirectives,
        int roundIndex
) {
    public static final double TARGET_APPROVAL_SCORE = 9.2;

    public VisionAuditReport {
        Objects.requireNonNull(deonticGateResult, "deonticGateResult cannot be null");
        Objects.requireNonNull(correctionDirectives, "correctionDirectives cannot be null");
        if (overallScore < 0.0 || overallScore > 10.0) {
            throw new IllegalArgumentException("overallScore must be between 0.0 and 10.0");
        }
    }

    public boolean isApproved() {
        return overallScore >= TARGET_APPROVAL_SCORE && deonticGateResult.allGatesPassed();
    }
}
